<script setup>
import { computed, onMounted, ref } from 'vue'
import { PerformanceRepository } from '../repositories/performanceRepository.js'
import { derivePerformance, layerRows, previousRange } from '../domain/performance/performanceEngine.js'

const PERIODS = ['DAY','WEEK','MONTH','3 MONTHS','6 MONTHS','1 YEAR','MULTI-YEAR','TILL DATE','CUSTOM RANGE']
const LAYERS = { target:['Position','Pace & projection','Target drivers','Comparison','Detailed period'], revenue:['Revenue position','Revenue composition','Revenue efficiency','Time & trend','Detailed revenue'], cost:['Break-even position','Cost drivers','Cost movement','Break-even analysis','Detailed costs'], profit:['Profit position','Provision position','Provision buckets','After provisions','Profit trend','Detailed financial records'] }
const period=ref('MONTH'), navigatorOpen=ref(false), activeCard=ref(null), activeLayer=ref(0), customFrom=ref(''), customTo=ref(''), loading=ref(true), error=ref('')
const snapshot=ref({shifts:[],trips:[],fuelLogs:[]})
const money=v=>Number.isFinite(v)?`₹${Math.round(v).toLocaleString('en-IN')}`:'—'
const num=v=>Number.isFinite(v)?v.toLocaleString('en-IN',{maximumFractionDigits:1}):'—'
const pct=v=>Number.isFinite(v)?`${v.toFixed(1)}%`:'—'
const range=computed(()=>{const now=new Date();let from=new Date(now),to=new Date(now);if(period.value==='CUSTOM RANGE'&&customFrom.value&&customTo.value)return{from:new Date(`${customFrom.value}T00:00:00`),to:new Date(`${customTo.value}T23:59:59.999`)};if(period.value==='DAY')from.setHours(0,0,0,0);else if(period.value==='WEEK'){from.setHours(0,0,0,0);from.setDate(from.getDate()-((from.getDay()+6)%7))}else if(period.value==='MONTH')from=new Date(now.getFullYear(),now.getMonth(),1);else if(period.value==='3 MONTHS')from.setMonth(from.getMonth()-3);else if(period.value==='6 MONTHS')from.setMonth(from.getMonth()-6);else if(period.value==='1 YEAR')from.setFullYear(from.getFullYear()-1);else if(period.value==='MULTI-YEAR')from.setFullYear(from.getFullYear()-5);else if(period.value==='TILL DATE')from=new Date(0);return{from,to}})
const metrics=computed(()=>derivePerformance(snapshot.value,range.value,previousRange(range.value)))
const activeRows=computed(()=>activeCard.value?layerRows(activeCard.value,activeLayer.value,metrics.value):[])
const cards=computed(()=>({target:{title:'🎯 Target & Position',rows:[['Achieved revenue',money(metrics.value.revenue)],['Target',metrics.value.target==null?'Not configured':money(metrics.value.target)],['Status',metrics.value.target==null?'Target not configured':'Calculated']]},revenue:{title:'💰 Revenue',rows:[['Total revenue',money(metrics.value.revenue)],['Revenue/KM',money(metrics.value.revenuePerKm)],['Revenue/trip',money(metrics.value.revenuePerTrip)]]},cost:{title:'🧾 Cost & Break-even',rows:[['Actual operating cost',money(metrics.value.actualOperatingCost)],['Maintenance provision',money(metrics.value.maintenanceProvision)],['Break-even basis',money(metrics.value.actualOperatingCost+metrics.value.maintenanceProvision)]]},profit:{title:'🏦 Profit & Provisions',rows:[['Actual profit/loss',money(metrics.value.actualProfit)],['Available profit',money(metrics.value.availableProfit)],['Provision set aside',money(metrics.value.provisionSetAside)]]}}))
const layerTitle=computed(()=>activeCard.value?`${cards.value[activeCard.value].title.replace(/^\S+\s/,'')} — ${LAYERS[activeCard.value][activeLayer.value]}`:'')
function choosePeriod(p){period.value=p;if(p!=='CUSTOM RANGE')navigatorOpen.value=false}
function applyCustom(){if(customFrom.value&&customTo.value){period.value='CUSTOM RANGE';navigatorOpen.value=false}}
function openCard(k){activeCard.value=k;activeLayer.value=0}
function back(){if(activeLayer.value)activeLayer.value--;else activeCard.value=null}
function next(){if(activeCard.value&&activeLayer.value<LAYERS[activeCard.value].length-1)activeLayer.value++}
onMounted(async()=>{try{snapshot.value=await PerformanceRepository.getSnapshot()}catch(e){error.value=e?.message||'Performance data could not be loaded.'}finally{loading.value=false}})
</script>
<template><section class="performance-page"><div v-if="loading" class="state">Loading Performance…</div><div v-else-if="error" class="state error">{{error}}</div><template v-else-if="!activeCard"><header class="head"><div><small>PERFORMANCE</small><h1>Business position</h1></div><button class="period" @click="navigatorOpen=true">{{period}}⌄</button></header><div class="grid"><button v-for="key in ['target','revenue','cost','profit']" :key="key" class="box" @click="openCard(key)"><h2>{{cards[key].title}}</h2><div v-for="r in cards[key].rows" :key="r[0]" class="row"><span>{{r[0]}}</span><strong>{{r[1]}}</strong></div><em>View detail →</em></button></div><section class="pulse"><small>OPERATIONAL PULSE</small><h2>What matters now</h2><div class="pulse-grid"><div><span>Vehicle KM</span><b>{{num(metrics.vehicleKm)}}</b></div><div><span>Business KM</span><b>{{num(metrics.businessKm)}}</b></div><div><span>Trips</span><b>{{num(metrics.counts.trips)}}</b></div><div><span>Fuel cost</span><b>{{money(metrics.fuelCost)}}</b></div></div></section></template><template v-else><header class="head"><button class="back" @click="back">‹</button><div><small>PERFORMANCE</small><h1>{{layerTitle}}</h1></div><button v-if="activeLayer<LAYERS[activeCard].length-1" class="next" @click="next">Next ›</button></header><section class="detail"><div class="tabs"><button v-for="(l,i) in LAYERS[activeCard]" :key="l" :class="{active:i===activeLayer}" @click="activeLayer=i">{{i+1}}. {{l}}</button></div><h2>{{LAYERS[activeCard][activeLayer]}}</h2><p>Period: <b>{{period}}</b></p><div class="detail-grid"><div v-for="(r,i) in activeRows" :key="i"><span>{{r[0]}}</span><b>{{r.slice(1).join(' · ')}}</b></div></div><div class="note">Read-only interpretation of authoritative KFE records. Target, loan, compliance and hourly metrics remain visibly unavailable until their authoritative inputs exist; no substitute or fake values are used.</div></section></template><div v-if="navigatorOpen" class="overlay"><section class="navigator"><header><div><small>PERIOD</small><h2>Choose reporting range</h2></div><button @click="navigatorOpen=false">✕</button></header><div class="periods"><button v-for="p in PERIODS" :key="p" :class="{selected:period===p}" @click="choosePeriod(p)">{{p}}<span>›</span></button></div><div v-if="period==='CUSTOM RANGE'" class="custom"><label>From<input v-model="customFrom" type="date"></label><label>To<input v-model="customTo" type="date"></label><button @click="applyCustom">Apply range</button></div></section></div></section></template>
<style scoped>.performance-page{min-height:100%;padding:16px;box-sizing:border-box;color:#0f172a;max-width:760px;margin:auto}.head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px}.head small,.pulse small{font-size:.68rem;font-weight:800;color:#64748b;letter-spacing:.08em}.head h1{font-size:1.22rem;margin:3px 0 0}.period,.back,.next,.navigator header button{border:1px solid #cbd5e1;background:#fff;border-radius:10px;padding:9px 11px;font-weight:800}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.box,.pulse,.detail{background:#fff;border:1px solid #e2e8f0;border-radius:16px}.box{min-height:190px;padding:15px;text-align:left;box-shadow:0 3px 12px rgba(15,23,42,.04)}.box h2{font-size:.96rem;margin:0 0 14px}.row{display:flex;justify-content:space-between;gap:8px;padding:7px 0;border-top:1px solid #f1f5f9;font-size:.75rem}.row strong{text-align:right;font-size:.78rem}.box em{display:block;margin-top:12px;color:#2563eb;font-style:normal;font-size:.74rem;font-weight:800}.pulse{margin-top:12px;padding:15px}.pulse h2{font-size:1rem;margin:3px 0 10px}.pulse-grid,.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pulse-grid div,.detail-grid div{background:#f8fafc;border-radius:10px;padding:10px}.pulse-grid span,.detail-grid span{display:block;color:#64748b;font-size:.7rem}.pulse-grid b,.detail-grid b{display:block;margin-top:3px}.state{padding:24px;background:#fff;border:1px solid #e2e8f0;border-radius:16px;text-align:center}.error{color:#b91c1c}.back{font-size:1.3rem;padding:4px 11px}.next{color:#2563eb}.detail{padding:14px}.tabs{display:flex;gap:7px;overflow-x:auto;padding-bottom:10px}.tabs button{white-space:nowrap;border:1px solid #e2e8f0;background:#f8fafc;border-radius:999px;padding:7px 10px;font-size:.7rem;font-weight:800}.tabs button.active{background:#0f172a;color:#fff}.detail h2{font-size:1.08rem;margin:10px 0 4px}.detail p{color:#64748b;font-size:.78rem}.detail-grid{margin-top:12px}.note{margin-top:14px;padding:12px;border-radius:10px;background:#f8fafc;color:#475569;font-size:.75rem;line-height:1.45}.overlay{position:fixed;inset:0;background:rgba(15,23,42,.48);z-index:10000;display:flex;align-items:flex-end}.navigator{width:100%;max-height:88vh;overflow:auto;background:#fff;border-radius:20px 20px 0 0;padding:18px;box-sizing:border-box}.navigator header{display:flex;justify-content:space-between;align-items:flex-start}.navigator h2{font-size:1.1rem;margin:3px 0 14px}.periods{display:grid;gap:7px}.periods button{display:flex;justify-content:space-between;border:1px solid #e2e8f0;background:#f8fafc;border-radius:11px;padding:12px;font-weight:800}.periods button.selected{border-color:#2563eb;background:#eff6ff;color:#1d4ed8}.custom{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.custom label{font-size:.72rem;font-weight:800}.custom input{display:block;width:100%;box-sizing:border-box;margin-top:5px;padding:10px;border:1px solid #cbd5e1;border-radius:9px}.custom button{grid-column:1/-1;padding:11px;border:0;border-radius:10px;background:#0f172a;color:#fff;font-weight:800}@media(max-width:430px){.grid{gap:8px}.box{padding:12px;min-height:185px}.performance-page{padding:12px}}</style>